const raw =
  $json.content ??
  $json.text ??
  $json.output ??
  $json.response ??
  '';

if (!raw) {
  throw new Error('Vision extraction returned an empty response');
}

let parsed;

try {
  let cleaned = String(raw).trim();

  // Remove markdown JSON fences
  cleaned = cleaned
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  parsed = JSON.parse(cleaned);
} catch (error) {
  throw new Error(
    `Vision extraction returned invalid JSON: ${error.message}`
  );
}

const requiredStructure = [
  'vendor_name',
  'invoice_number',
  'invoice_date',
  'due_date',
  'total_amount',
  'currency',
  'tax_amount',
  'category',
  'department',
  'subtotal',
  'confidence'
];

for (const field of requiredStructure) {
  if (!(field in parsed)) {
    parsed[field] = null;
  }
}

return [{
  json: {
    ...$json,
    ...parsed,
    ai_parse_status: 'SUCCESS',
    extraction_source: 'OPENAI_VISION'
  },
  binary: $binary
}];

