const fileKey = 'invoice';
const file = $binary?.[fileKey];
const mimeType = file.mimeType || '';

const allowedMimeTypes = [
  'application/pdf',
  'image/png',
  'image/jpeg'
];

const maxFileSize = 10 * 1024 * 1024;
const errors = [];

if (!file) {
  errors.push('Invoice file was not found under binary property: invoice');
} else {
  if (!allowedMimeTypes.includes(file.mimeType)) {
    errors.push(`Unsupported file type: ${file.mimeType}`);
  }

  if (file.fileSize && Number(file.fileSize) > maxFileSize) {
    errors.push('Invoice file exceeds the 10 MB limit');
  }
}

return [
  {
    json: {
      ...$json,
      file_key: fileKey,
      file_name: file?.fileName || null,
      file_type: file?.mimeType || null,
      file_valid: errors.length === 0,
      file_validation_errors: errors,
      is_pdf: mimeType === 'application/pdf',
      is_image: mimeType.startsWith('image/')
    },
    binary: $binary
  }
];

const text = ($json.text || '').trim();

return [{
  json: {
    ...$json,
    extracted_text: text,
    text_available: text.length >= 50,
    text_length: text.length,
    extraction_status:
        text.length >= 30 ? 'TEXT_AVAILABLE' : 'TEXT_EMPTY'
  },
  binary: $binary
}];

const text =
  $json.extracted_text ||
  $json.text ||
  $json.ocr_text ||
  '';

const normalized = text
  .replace(/\r/g, '\n')
  .replace(/[ \t]+/g, ' ')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

return [{
  json: {
    ...$json,
    invoice_text: normalized,
    normalized_text_length: normalized.length,
    normalized_text_available: text.length >= 30,
    processing_status: 'TEXT_READY'
  },
  binary: $binary
}];

const requiredFields = [
  'vendor_name',
  'invoice_number',
  'invoice_date',
  'total_amount',
  'currency'
];

const missingFields = requiredFields.filter(field => {
  const value = $json[field];

  return (
    value === null ||
    value === undefined ||
    String(value).trim() === ''
  );
});

return [{
  json: {
    ...$json,
    missing_fields: missingFields,
    required_fields_valid: missingFields.length === 0
  },
  binary: $binary
}];

const reasons = [];

if ($json.missing_fields?.length) {
  reasons.push(
    `Missing fields: ${$json.missing_fields.join(', ')}`
  );
}

if ($json.amount_validation === 'FAILED') {
  reasons.push('Invoice amount validation failed');
}

if ($json.date_validation === 'FAILED') {
  reasons.push('Invoice date validation failed');
}

if (
  typeof $json.overall_confidence === 'number' &&
  $json.overall_confidence < 0.70
) {
  reasons.push('AI extraction confidence is below 70%');
}

return [{
  json: {
    ...$json,

    review_reason: reasons.length
      ? reasons.join('; ')
      : 'Invoice requires manual review',

    review_status: 'PENDING',

    review_confidence:
      Number($json.overall_confidence || 0)
  },

  binary: $binary
}];

const confidence = $json.confidence || {};

const values = Object.values(confidence)
  .filter(value =>
    typeof value === 'number' &&
    value >= 0 &&
    value <= 1
  );

const overallConfidence = values.length
  ? values.reduce((sum, value) => sum + value, 0) / values.length
  : 0;

let confidenceStatus = 'LOW';

if (overallConfidence >= 0.90) {
  confidenceStatus = 'HIGH';
} else if (overallConfidence >= 0.70) {
  confidenceStatus = 'MEDIUM';
}

return [{
  json: {
    ...$json,
    overall_confidence: Number(
      overallConfidence.toFixed(4)
    ),
    confidence_status: confidenceStatus
  },
  binary: $binary
}];

const subtotal =
  $json.subtotal !== null &&
  $json.subtotal !== undefined
    ? Number($json.subtotal)
    : null;

const tax =
  $json.tax_amount !== null &&
  $json.tax_amount !== undefined
    ? Number($json.tax_amount)
    : null;

const total = Number($json.total_amount);

let amountValidation = 'PASSED';
let amountDifference = null;

if (!Number.isFinite(total) || total <= 0) {
  amountValidation = 'FAILED';
}

if (
  subtotal !== null &&
  tax !== null &&
  Number.isFinite(subtotal) &&
  Number.isFinite(tax)
) {
  const calculatedTotal = subtotal + tax;

  amountDifference = Math.abs(
    calculatedTotal - total
  );

  if (amountDifference > 0.05) {
    amountValidation = 'FAILED';
  }
}

let dateValidation = 'PASSED';

if ($json.invoice_date && $json.due_date) {
  const invoiceDate = new Date($json.invoice_date);
  const dueDate = new Date($json.due_date);

  if (dueDate < invoiceDate) {
    dateValidation = 'FAILED';
  }
}

return [{
  json: {
    ...$json,
    calculated_total:
      subtotal !== null && tax !== null
        ? subtotal + tax
        : null,
    amount_difference: amountDifference,
    amount_validation: amountValidation,
    date_validation: dateValidation
  },
  binary: $binary
}];

let riskScore = 0;
const reasons = [];

const total = Number($json.total_amount || 0);

if (total >= 10000) {
  riskScore += 30;
  reasons.push('High invoice amount');
} else if (total >= 5000) {
  riskScore += 15;
  reasons.push('Medium invoice amount');
}

if (!$json.due_date) {
  riskScore += 10;
  reasons.push('Due date is missing');
}

if (!$json.invoice_number) {
  riskScore += 20;
  reasons.push('Invoice number is missing');
}

if (
  $json.tax_amount !== null &&
  Number($json.tax_amount) > total
) {
  riskScore += 30;
  reasons.push('Tax exceeds invoice total');
}

if (
  $json.overall_confidence !== undefined &&
  $json.overall_confidence < 0.85
) {
  riskScore += 15;
  reasons.push('AI extraction confidence below 85%');
}

riskScore = Math.min(riskScore, 100);

let riskLevel = 'LOW';

if (riskScore >= 70) {
  riskLevel = 'HIGH';
} else if (riskScore >= 40) {
  riskLevel = 'MEDIUM';
}

return [{
  json: {
    ...$json,
    risk_score: riskScore,
    risk_level: riskLevel,
    approval_reason: reasons.length
      ? reasons.join('; ')
      : 'No significant risk factors detected'
  },
  binary: $binary
}];

const duplicate = $input.first()?.json;

return [{
  json: {
    ...$json,
    duplicate_found: !!duplicate?.invoice_id || Boolean(duplicate && duplicate.id),
    existing_invoice_id: duplicate?.invoice_id || duplicate?.id || null
  },
  binary: $binary
}];

