const timestamp = new Date()
  .toISOString()
  .replace(/[-:.TZ]/g, '');

const randomPart = Math.random()
  .toString(36)
  .substring(2, 8)
  .toUpperCase();

const invoiceId = `INV-${timestamp}-${randomPart}`;

return [{
  json: {
    ...$json,
    invoice_id: invoiceId
  },
  binary: $binary
}];

const input = $json;
const binary = $binary || {};
const errors = [];
const body = $json.body || $json;


const file = binary.invoice;

if (!file) {
  errors.push('Invoice file is missing');
}

if (!body.submitted_by) { errors.push('submitted_by is required'); }
if (!body.department) { errors.push('department is required'); }

return [
  {
    json: {
      ...input,
      request_valid: errors.length === 0,
      request_validation_errors: errors
    },
    binary
  }
];

let riskScore = 0;
const reasons = [];

const total = Number($json.total_amount || 0);

if (total <= 0) {
  reasons.push('Invoice total must be greater than zero');
}

if (
  $json.tax_amount != null &&
  Number($json.tax_amount) > total
) {
  reasons.push('Tax amount exceeds invoice total');
}

if (
  $json.invoice_date &&
  new Date($json.invoice_date) > new Date()
) {
  reasons.push('Invoice date is in the future');
}

if (
  $json.due_date &&
  $json.invoice_date &&
  new Date($json.due_date) <
  new Date($json.invoice_date)
) {
  reasons.push('Due date is before invoice date');
}

return [{
  json: {
    ...$json,

    business_rule_status:
      reasons.length === 0
        ? 'PASSED'
        : 'FAILED',

    business_rule_reasons: reasons
  }
}];
